foundation.question_text:
The bottom side is the base. Which labelled segment is its perpendicular height?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (A) at (0,0);
\coordinate (B) at (5,0);
\coordinate (C) at (6.4,2.8);
\coordinate (D) at (1.4,2.8);
\coordinate (H) at (1.4,0);
\draw (A)--(B) node[midway,below] {base};
\draw (B)--(C) node[midway,right] {$p$};
\draw (C)--(D)--(A);
\draw[dashed] (D)--(H) node[midway,right] {$q$};
\coordinate (ra) at ($(H)!0.3cm!(D)$);
\coordinate (rb) at ($(H)!0.3cm!(B)$);
\draw (ra)--($(ra)+(rb)-(H)$)--(rb);
\end{tikzpicture}
[/tikz]

foundation.solution_text:
Segment $q$ meets the base at the marked right angle.
$q$ is the perpendicular height.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (A) at (0,0);\coordinate (B) at (5,0);\coordinate (C) at (6.4,2.8);\coordinate (D) at (1.4,2.8);\coordinate (H) at (1.4,0);
\draw (A)--(B) node[midway,below] {base};\draw (B)--(C) node[midway,right] {$p$};\draw (C)--(D)--(A);
\draw[thick,dashed] (D)--(H) node[midway,right] {$q$ (height)};
\coordinate (ra) at ($(H)!0.3cm!(D)$);\coordinate (rb) at ($(H)!0.3cm!(B)$);\draw (ra)--($(ra)+(rb)-(H)$)--(rb);
\end{tikzpicture}
[/tikz]

